/** Browser verification for the EXO AccuMark research tool drawer.
 * Requires an existing Vite dev server (default http://127.0.0.1:5174).
 * Creates an isolated browser context. No existing user project is changed.
 */
import assert from 'node:assert/strict'
import {chromium} from 'playwright-core'

// The AccuMark grading library edits the legacy project. The native Rust
// workspace intentionally disables those legacy-grade inputs.
const url=process.env.EXO_ACCUMARK_UI_URL||'http://127.0.0.1:5174/?desktop=1'
const browser=await chromium.launch({headless:true,executablePath:process.env.EXO_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--disable-gpu','--no-first-run']})
try{
 const page=await browser.newPage({viewport:{width:1720,height:1040}}),errors=[]
 page.on('pageerror',error=>errors.push(error.message))
 await page.goto(url,{waitUntil:'domcontentloaded',timeout:25000})
 await page.getByRole('combobox',{name:'3D and 2D window arrangement'}).selectOption('2d')
 await page.locator('.exo-accu-launch').click()
 assert.equal(await page.locator('[data-accumark-grade-actions]').count(),1)
 const gradeSelect=page.getByRole('combobox',{name:'Grade preview size'})
 const previewSizes=await gradeSelect.locator('option').count()
 assert(previewSizes>=2)
 const before=await gradeSelect.inputValue()
 const option=(await gradeSelect.locator('option').evaluateAll(items=>items.map(item=>item.value))).find(size=>size!==before)
 await gradeSelect.selectOption(option)
 assert.equal(await gradeSelect.inputValue(),option)
 const linkedGrade=page.locator('[data-modaris-linked-grading-study]')
 assert.equal(await linkedGrade.count(),1,'The source-linked grading editor must be mounted in the real legacy 2D drawer')
 await linkedGrade.locator('summary').click()
 assert.equal(await linkedGrade.getByRole('combobox',{name:'Source grading point'}).count(),1)
 const linkedNotches=page.locator('[data-modaris-graded-notch-link-study]')
 assert.equal(await linkedNotches.count(),1,'Source-linked graded notch research tool must be in the 2D Grading drawer')
 await linkedNotches.locator('summary').click()
 assert.equal(await linkedNotches.getByRole('combobox',{name:'Linked notch source'}).count(),1)
 assert.equal(await linkedNotches.getByRole('button',{name:'Preview verified linked notch sizes'}).count(),1)
 const curvedNotches=page.locator('[data-modaris-curved-graded-notch-study]')
 assert.equal(await curvedNotches.count(),1,'Physical arclength graded curved notch editor must be in the 2D Grading drawer')
 await curvedNotches.locator('summary').click()
 assert.equal(await curvedNotches.getByRole('combobox',{name:'Curved notch source'}).count(),1)
 assert.equal(await curvedNotches.getByRole('button',{name:'Stage physical graded notch diagnostics'}).count(),1)
 const industrialEvidence=page.locator('[data-modaris-industrial-six-size-witness]')
 assert.equal(await industrialEvidence.count(),1,'Six-size physical CUT/STITCH independent receiver evidence must be available in 2D Grading')
 await industrialEvidence.locator('summary').click()
 assert.equal(await industrialEvidence.getByRole('button',{name:'Audit all six physical sizes and DXF geometry'}).count(),1)
 const nest=page.getByRole('checkbox',{name:'Show grade nest'}),wasNest=await nest.isChecked()
 await nest.click()
 assert.notEqual(await nest.isChecked(),wasNest)
 const enable=page.getByRole('button',{name:/Enable independent size breaks for point/i})
 if(await enable.count()){
  await enable.first().click()
  await page.locator('.exo-accu-library .industrial-grade-breaks').first().waitFor()
 }
 const advanced=page.locator('[data-accumark-engineering-controls]')
 assert.equal(await advanced.count(),1)
 await advanced.locator('summary').first().click()
 assert.equal(await advanced.getByRole('button',{name:'Apply Offset'}).count(),1)
 // The library now has several independent constraint studies. Choose the
 // precise constraint authoring section instead of an ambiguous summary.
 await page.locator('.exo-accu-constraint-box > details > summary').filter({hasText:'Match Line · Keep Angle'}).click()
 const constraint=page.getByRole('combobox',{name:'Constraint operation'})
 assert.equal(await constraint.count(),1)
 await constraint.selectOption('parallel')
 assert.equal(await constraint.inputValue(),'parallel')
 await page.locator('.exo-accu-production summary').filter({hasText:'Marker layout, quantities and physical plot QA'}).click()
 assert.equal(await page.locator('[data-accumark-production-controls]').count(),1)
 await page.getByRole('button',{name:'Validate 100 mm plot ruler'}).click()
 assert.match(await page.locator('.exo-accu-production').innerText(),/both plot axes within/i)
 await page.getByRole('button',{name:'33 functions'}).click()
 const named=page.locator('.exo-named-rules')
 assert.equal(await named.count(),1)
 await named.locator('summary').click()
 assert.equal(await named.getByRole('button',{name:'Download library JSON'}).count(),1)
 const digitizing=page.locator('.exo-accu-digitizing-box')
 assert.equal(await digitizing.count(),1)
 await digitizing.locator('summary').click()
 assert.equal(await digitizing.getByRole('button',{name:'Import traced piece'}).count(),1)
 assert.equal(await page.locator('.exo-accu-command').count(),33)
 await page.locator('[data-accumark-command="accu.grading.delta"] .exo-accu-command-title').click()
 assert.equal(await page.locator('[data-accumark-command="accu.grading.delta"] .exo-accu-engineering > div').count(),6)
 await page.getByRole('button',{name:'116 references'}).click()
 assert.equal(await page.locator('.exo-accu-command').count(),116)
 await page.getByRole('searchbox',{name:'Search 2D engineering tools'}).fill('Grade Options')
 assert.equal(await page.locator('.exo-accu-command').count(),1)
 await page.getByRole('button',{name:'Advanced CAD',exact:true}).click()
 const derived=page.locator('[data-modaris-derived-contour-study]')
 const trueing=page.locator('[data-modaris-straight-seam-trueing]')
 const curved=page.locator('[data-modaris-curved-seam-trueing]')
 const connectedFacing=page.locator('[data-modaris-connected-industrial-derivative]')
 assert.equal(await derived.count(),1,'Qualified derived-contour study must be in the live Advanced CAD drawer')
 assert.equal(await trueing.count(),1,'Qualified seam-trueing study must be in the live Advanced CAD drawer')
 assert.equal(await curved.count(),1,'Qualified curved seam-trueing study must be in the live Advanced CAD drawer')
 assert.equal(await connectedFacing.count(),1,'Six-size connected rectangular facing study must be in the live Advanced CAD drawer')
 await connectedFacing.locator('summary').click()
 assert.equal(await connectedFacing.getByRole('button',{name:'Calculate six-size preview'}).count(),1)
 await derived.locator('summary').click()
 assert.equal(await derived.getByRole('button',{name:'Create geometric inward contour study'}).count(),1)
 await trueing.locator('summary').click()
 assert.equal(await trueing.getByRole('button',{name:'Inspect and preview seam correction'}).count(),1)
 await curved.locator('summary').click()
 assert.equal(await curved.getByRole('button',{name:'Stage curved seam preview'}).count(),1)
 assert.deepEqual(errors,[])
 console.log(JSON.stringify({pass:true,functions:33,helpEntries:116,gradePreviewSizes:previewSizes,nestToggle:true,gradingEditor:true,engineeringDetails:true,advancedGrading:true,gradingConstraints:true,markerAndPlot:true,namedRuleLibrary:true,manualDigitizing:true,linkedSizeGradingUI:true,linkedGradedNotchUI:true,gradedCurvedNotchUI:true,derivedContourUI:true,straightSeamTrueingUI:true,curvedSeamTrueingUI:true,pageErrors:0}))
}finally{await browser.close()}
